CREATE TABLE IF NOT EXISTS curriculum_review_notes (id VARCHAR(32) PRIMARY KEY,reviewer_id VARCHAR(32) NOT NULL,course_id VARCHAR(32) NOT NULL,module_index INTEGER NOT NULL,page_key VARCHAR(100) NOT NULL,note TEXT NOT NULL,version INTEGER NOT NULL,created_at VARCHAR(30) NOT NULL,UNIQUE(reviewer_id,course_id,module_index,page_key,version),FOREIGN KEY(reviewer_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
